/**
 * Generate the frontend theme catalog from the same curated source used by
 * db/migrate.js. This only writes the checked-in frontend catalog; it never
 * connects to or mutates a database.
 *
 * Run: node scripts/gen-theme-data.js
 */
import { writeFileSync } from 'node:fs';
import { buildPresets } from './themeCatalog.js';

const presets = buildPresets();
const output = [
  '/**',
  ' * Generated by scripts/gen-theme-data.js from scripts/themeCatalog.js.',
  ' * Do not edit by hand; preserve stable ids in the curated catalog source.',
  ' */',
  '',
  `export const THEME_DATA = ${JSON.stringify(presets, null, 2)};`,
  '',
  'export const THEME_BY_ID = Object.fromEntries(THEME_DATA.map((theme) => [theme.id, theme]));',
  '',
].join('\n');

writeFileSync('src/components/storefront/templates/themeComponents/themeData.js', output);
console.log(`Generated ${presets.length} curated themes.`);
